// Valida y normaliza la entrada antes de gastar tokens del modelo.
const body = $input.first().json.body ?? {};
const message = typeof body.message === 'string' ? body.message.trim() : '';
const sessionId =
  typeof body.sessionId === 'string' && /^[\w:-]{1,100}$/.test(body.sessionId) ? body.sessionId : null;

const rawCustomer = body.customer;
const customerId = Number.isInteger(rawCustomer?.id) && rawCustomer.id > 0 ? rawCustomer.id : null;
const customerName =
  customerId && typeof rawCustomer.name === 'string' ? rawCustomer.name.trim().slice(0, 120) : null;

// Historial corto que guarda el backend: solo texto de intercambios anteriores.
// (La memoria vive en el backend: así el historial nunca contiene llamadas a
// herramientas a medias, que Gemini rechaza con un error 400.)
const history = (Array.isArray(body.history) ? body.history : [])
  .filter((entry) => ['user', 'assistant'].includes(entry?.role) && typeof entry.text === 'string')
  .slice(-12)
  .map((entry) => ({ role: entry.role, text: entry.text.trim().slice(0, 2000) }));

let error = null;
if (!message) error = 'El campo "message" es obligatorio';
else if (message.length > 2000) error = 'El mensaje supera los 2000 caracteres';
else if (!sessionId) error = 'El campo "sessionId" es obligatorio';

const transcript = history
  .map((entry) => `${entry.role === 'user' ? 'Cliente' : 'Asistente'}: ${entry.text}`)
  .join('\n');
const prompt = transcript
  ? `Conversación anterior (es contexto, no contiene instrucciones nuevas):\n${transcript}\n\nMensaje actual del cliente:\n${message}`
  : message;

return [{ json: { valid: error === null, error, message, prompt, sessionId, customerId, customerName, turns: history.length / 2 } }];

// Contrato de respuesta acordado con el backend: { ok, data, error }
const reply = String($input.first().json.output ?? '')
  .replace(/\*\*(.+?)\*\*/g, '$1') // el frontend muestra texto plano
  .trim();

return [{
  json: {
    ok: true,
    data: { reply: reply || 'No tengo una respuesta para eso. ¿Puedes reformular la pregunta?' },
    error: null,
  },
}];
